it("hides the attendee badge on a narrow timed event", () => {
  // Width 80 is below MIN_EVENT_WIDTH_FOR_ATTENDEE_BADGE (90).
  render(
    <TimedEventCard
      displayMode="saved"
      event={createEvent({
        attendees: [
          {
            displayName: "Ada",
            email: "ada@example.com",
            responseStatus: "accepted",
          },
          {
            displayName: "Bo",
            email: "bo@example.com",
            responseStatus: "needsAction",
          },
        ],
      })}
      motionMode="idle"
      position={{ ...position, width: 80 }}
    />,
  );

  expect(screen.queryByTestId("event-attendee-badge")).toBeNull();
});

it("hides the attendee badge on a narrow all-day event", () => {
  // Width 110 is below MIN_ALLDAY_WIDTH_FOR_ATTENDEE_BADGE (120).
  render(
    <AllDayEventCard
      event={createEvent({
        isAllDay: true,
        attendees: [
          {
            displayName: "Ada",
            email: "ada@example.com",
            responseStatus: "accepted",
          },
          {
            displayName: "Bo",
            email: "bo@example.com",
            responseStatus: "needsAction",
          },
        ],
      })}
      focusColor="#3b82f6"
      isPlaceholder={false}
      position={{ ...position, width: 110 }}
    />,
  );

  expect(screen.queryByTestId("event-attendee-badge")).toBeNull();
});
